record.field:
move_lines = records.filtered(lambda sml: not sml.lot_id.x_warranty_date and sml.product_id.expiration_time)
for line in move_lines:
    line.lot_id.write({'x_warranty_date': datetime.datetime.today() + datetime.timedelta(line.product_id.expiration_time)})

for slot in records:
    if lead := slot.x_opportunity_name or (slot.partner_id and env['crm.lead'].search([('partner_id', '=', slot.partner_id.id)], limit=1)):
        technician = slot.user_ids[0] if slot.user_ids else env.user
        if env['x_crm_lead_check_log'].search([('x_lead_id', '=', lead.id), ('x_user_id', '=', technician.id), ('x_check_out_time', '=', False)], limit=1):
            continue
        geo = env.context.get('geolocation') or {}
        lat, lng = (geo.get('latitude'), geo.get('longitude')) if geo.get('success') else (0.0, 0.0)
        if lat and lng:
            localisation = env['base.geocoder']._get_localisation(latitude=lat, longitude=lng)
            label = localisation or ('%.6f, %.6f' % (lat, lng))
            maps_url = 'https://maps.google.com/?q=%s,%s' % (lat, lng)
            location_html = '<p><a href="%s" target="_blank" style="color:#00a09d">%s</a></p>' % (maps_url, label)
        else:
            label, maps_url, location_html = 'On Site', '', '<p>On Site</p>'
        now = datetime.datetime.now()
        env['x_crm_lead_check_log'].create({'x_date': now.date(), 'x_user_id': technician.id, 'x_lead_id': lead.id, 'x_check_in_time': now, 'x_check_in_location': location_html})
        lead.message_post(body='<p>Checked in: %s</p>' % ('<a href="%s" target="_blank" style="color:#00a09d">%s</a>' % (maps_url, label) if maps_url else label), body_is_html=True)

for slot in records:
    if lead := slot.x_opportunity_name or (slot.partner_id and env['crm.lead'].search([('partner_id', '=', slot.partner_id.id)], limit=1)):
        technician = slot.user_ids[:1] or env.user
        if open_log := env['x_crm_lead_check_log'].search([('x_lead_id', '=', lead.id), ('x_user_id', '=', technician.id), ('x_check_out_time', '=', False)], limit=1):
            location_html = str(open_log.x_check_in_location or '<p>On Site</p>')
            now = datetime.datetime.now()
            duration = (lambda m: m // 60 + (m % 60) / 100)(int((now - open_log.x_check_in_time).total_seconds() / 60)) if open_log.x_check_in_time else 0.0
            open_log.write({'x_check_out_time': now, 'x_check_out_location': location_html, 'x_duration': duration})
            lead.message_post(body='<p>Signed out: %s</p>' % location_html[3:-4], body_is_html=True)

solar_service_tmpl = env.ref('solar_installation.product_template_8', raise_if_not_found=False)
lines = records.order_line.filtered(lambda l: not l.display_type and l.product_id and not ((solar_service_tmpl and l.product_id.product_tmpl_id == solar_service_tmpl) or 'installation' in l.product_id.name.lower()))
if selected := lines.filtered(lambda l: l.x_select):
    selected.write({'price_unit': 0.0})
if unselected := lines - selected:
    unselected.write({'price_unit': 0.0, 'product_uom_qty': 0.0})

for picking in records:
    if order := picking.sale_id:
        invoices = order.invoice_ids.filtered(lambda inv: inv.state == 'posted')
        paid_total = sum(inv.amount_total for inv in invoices if inv.payment_state in ('paid', 'in_payment'))
        is_fully_paid = invoices and order.currency_id.compare_amounts(paid_total, order.amount_total) >= 0
        is_partial = invoices and not is_fully_paid and any(inv.payment_state in ('not_paid', 'partial') for inv in invoices)
        if not is_partial:
            for line in order.order_line.filtered(lambda l: not l.display_type and l.product_uom_qty > 0):
                line.write({'qty_invoiced': line.qty_delivered})

sale_orders = records.invoice_line_ids.sale_line_ids.order_id
for order in sale_orders:
    invoices = order.invoice_ids.filtered(lambda inv: inv.state == 'posted')
    paid_total = sum(inv.amount_total for inv in invoices if inv.payment_state in ('paid', 'in_payment'))
    is_fully_paid = invoices and order.currency_id.compare_amounts(paid_total, order.amount_total) >= 0
    if is_fully_paid:
        for line in order.order_line.filtered(lambda l: not l.display_type and l.product_uom_qty > 0):
            line.write({'qty_invoiced': line.qty_delivered})

menu = env.ref('solar_installation.menu_x_crm_lead_check_log', raise_if_not_found=False)
if menu:
    menu.write({'active': record.x_crm_checkout_logs})
